[CmdletBinding()]
param([ValidateSet('codex','copilot','claude')][string]$Provider,[string]$ConfigPath=(Join-Path (Split-Path -Parent $PSScriptRoot) 'config\agents.json'),[string]$CodexHome)
Set-StrictMode -Version Latest;$ErrorActionPreference='Stop';Import-Module (Join-Path $PSScriptRoot 'AgentEcosystem.psm1') -Force;Import-Module (Join-Path $PSScriptRoot 'HybridRuntime.psm1') -Force;$config=Get-EcosystemConfig -ConfigPath $ConfigPath -CodexHome $CodexHome;$items=@()
foreach($entry in $config.providerRouting.providers.PSObject.Properties){$id=[string]$entry.Name;if($Provider -and $id -ne $Provider){continue};$command=[string]$entry.Value.command;$resolved=$null;try{$resolved=switch($id){'codex'{Resolve-CodexCliPath};'copilot'{Resolve-CopilotCliPath -Override $command};'claude'{Resolve-ClaudeCliPath -Override $command}}}catch{$resolved=$null};$installed=-not [string]::IsNullOrWhiteSpace([string]$resolved);$auth=if(-not $installed){'not-installed'}elseif($id -in @('copilot','claude')){'provider-login-available'}else{'application-session'};$items += [pscustomobject]@{provider=$id;installed=$installed;command=$resolved;authStatus=$auth;loginCommand=if($id -eq 'copilot'){'copilot login'}elseif($id -eq 'claude'){'claude auth login'}else{'Use the Codex application account session.'};storesSecrets=$false}}
[pscustomobject]@{providers=$items;generatedAtUtc=[DateTime]::UtcNow.ToString('o')}
